/* Placas base — datos extraídos línea a línea de forge-configurador.jsx (fase 1).
   ADD replica el add("mbo", …) original, sin valores por defecto;
   M replica el ayudante original con sus defaults. */
import type { Row, SpecOf, WithDefaults } from "./types";

