const ADD = (brand: string, name: string, price: number, o: SpecOf<"mbo">) => { rows.push({ brand, name, price, ...o }); };
const M = (brand: string, name: string, price: number, o: WithDefaults<SpecOf<"mbo">, "m2gen5" | "tb" | "bios_flashback">) =>
  ADD(brand, name, price, { m2gen5: 0, tb: false, bios_flashback: false, ...o });

